// Validate generated UUIDs and ISO timestamps, then substitute only the exact
// generated identity/time paths specified by the independent projection.
export function normalizeRestorableDealActual(actual,entry){
 const value=structuredClone(actual);delete value.viewer;delete value.mutationResult;const ids=new Map();
 for(const name of ['deals','orders','tasks','events']){const oldIds=new Set(entry.state[name].map(row=>row.id)),expected=entry.projection.state[name].filter(row=>!oldIds.has(row.id)),added=value[name].filter(row=>!oldIds.has(row.id));assert.equal(added.length,expected.length,'Exact independently projected new '+name+' count');const used=new Set();for(const row of added){const match=expected.find(item=>name==='events'?item.text===row.text&&item.kind===row.kind:name==='orders'?true:item.title===row.title&&item.customerId===row.customerId&&item.kind===row.kind);assert.ok(match&&!used.has(match.id),'Unique independently projected '+name+' identity');used.add(match.id);assert.match(row.id,/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/);ids.set(row.id,match.id);}}
 const identityFields=new Set(['id','customerId','dealId','convertedDealId','sourceDealId','sourceOrderId']);const substitute=(v,key)=>typeof v==='string'?identityFields.has(key)?ids.get(v)||v:v:Array.isArray(v)?v.map(x=>substitute(x,key)):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,substitute(x,k)])):v;
 const normalized=orderedRestorableDealState(substitute(value)),expected=orderedRestorableDealState(entry.projection.state);
 const temporal=(got,want,key)=>{if(want==='DIREKT-00000000'){assert.ok(['quoteRef','reference'].includes(key));assert.match(got,/^DIREKT-[a-f0-9]{8}$/);return want;}if(want===at){assert.ok(['at','createdAt','stageAt','doneAt','startedAt','priceCheckedAt'].includes(key));assert.equal(typeof got,'string');assert.equal(new Date(got).toISOString(),got);assert.equal(got.length,at.length);return at;}if(Array.isArray(want)){assert.ok(Array.isArray(got));assert.equal(got.length,want.length);return got.map((x,i)=>temporal(x,want[i],key));}if(want&&typeof want==='object'){assert.ok(got&&typeof got==='object');for(const key of Object.keys(want))got[key]=temporal(got[key],want[key],key);}return got;};
 return temporal(normalized,expected);
}

